323	// file by file.
324	var migratedSources = map[command.ViewType][]string{
325		command.ViewJobs: {"ui/jobsview/"},
326	}
327	
328	// sourceDeclarationProblems says what is wrong with the link between migrated
329	// views and the sources scanned for them, empty when it is fine. files are the
330	// paths relative to internal/ of every non-test source file.
331	func sourceDeclarationProblems(migrated map[command.ViewType][]string, sources map[command.ViewType][]string, files []string) []string {
332		var problems []string
