		{"exempt and pending fails", nil, pending, map[command.ViewType]string{v: "why"}, 1, nil, nil},
		{"pending table not reported is not stale", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
