402	// activityGlyphs are the runes of internal/ui/indicator; a view takes them from
403	// indicator.Glyph and never spells one.
404	const activityGlyphs = "●○◴⊗◐◕◉⊘⊖◌"
405	
406	// declaredViewTicks are the tea.Tick / tea.Every calls a migrated view may
407	// still make, keyed "<file relative to internal/>:<function>" with the reason.
408	// Empty today: the router's one tick animates every row (DEVDESK-139). The list
409	// may only shrink.
410	var declaredViewTicks = map[string]string{}
411	
412	// finding is one retired mechanism found in a source file.
413	type finding struct {
414		Pos  token.Position // file:line:column
415		What string
416	}
417	
418	// bubbleTeaName returns the local name file gives the bubbletea import: its
419	// alias, "." for a dot import, "tea" when unnamed, or "" when the file does not
420	// import it (or blank-imports it). A different package that happens to be
421	// called tea is therefore not mistaken for it.
422	func bubbleTeaName(file *ast.File) string {
423		for _, imp := range file.Imports {
424			path, err := strconv.Unquote(imp.Path.Value)
425			if err != nil || path != "github.com/charmbracelet/bubbletea" {
426				continue
427			}
428			switch {
429			case imp.Name == nil:
430				return "tea"
431			case imp.Name.Name == "_":
432				return ""
433			default:
434				return imp.Name.Name
435			}
436		}
437		return ""
438	}
439	
440	// retiredMechanisms reports, in a migrated view's file, every retired
441	// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
442	// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
443	// imports it) outside declaredViewTicks.
444	// rel is the file's path relative to internal/; it is the key of a declared tick.
445	// RenderedFrame (a method of the viewport frame) is allowed.
446	func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
447		var out []finding
448		report := func(pos token.Pos, what string) {
449			out = append(out, finding{Pos: fset.Position(pos), What: what})
450		}
451		tea := bubbleTeaName(file)
452		selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
453		// reportTick flags any reference to bubbletea's Tick / Every, called or not
454		// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`), unless the
455		// enclosing "<file>:<function>" is declared.
456		reportTick := func(pos token.Pos, fn, name string) {
457			if name != "Tick" && name != "Every" {
458				return
459			}
460			if _, declared := declaredViewTicks[rel+":"+fn]; !declared {
461				report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
462			}
463		}
464		isFrame := func(name string) bool {
465			return name == "Frame" || name == "frame" || name == "SpinnerFrame"
466		}
467		visit := func(fn string) func(ast.Node) bool {
468			return func(n ast.Node) bool {
469				switch x := n.(type) {
470				case *ast.CallExpr:
471					sel, ok := x.Fun.(*ast.SelectorExpr)
472					if !ok {
473						break
474					}
475					if sel.Sel.Name == "AdvanceSpinner" {
476						report(x.Pos(), "call to AdvanceSpinner")
477					}
478				case *ast.KeyValueExpr:
479					if id, ok := x.Key.(*ast.Ident); ok {
480						if id.Name == "StatusColumn" {
481							report(id.Pos(), "StatusColumn: key")
482						}
483						if isFrame(id.Name) {
484							report(id.Pos(), "frame field "+id.Name+": set")
485						}
486					}
487				case *ast.Field:
488					for _, id := range x.Names {
489						if isFrame(id.Name) {
490							report(id.Pos(), "frame field "+id.Name)
491						}
492					}
493				case *ast.Ident:
494					// Dot import: a bare Tick / Every that no declaration in the file binds.
495					if tea == "." && x.Obj == nil && !selectors[x] {
496						reportTick(x.Pos(), fn, x.Name)
497					}
498				case *ast.SelectorExpr:
499					selectors[x.Sel] = true
500					if pkg, ok := x.X.(*ast.Ident); ok && tea != "" && tea != "." && pkg.Name == tea {
501						reportTick(x.Pos(), fn, x.Sel.Name)
502					}
503					if isFrame(x.Sel.Name) {
504						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
505					}
506				case *ast.BasicLit:
507					if x.Kind == token.STRING || x.Kind == token.CHAR {
508						s, err := strconv.Unquote(x.Value)
509						if x.Kind == token.CHAR {
510							var q rune
511							q, _, _, err = strconv.UnquoteChar(x.Value[1:len(x.Value)-1], '\'')
512							s = string(q)
513						}
514						if err == nil && strings.ContainsAny(s, activityGlyphs) {
515							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
516						}
517					}
518				}
519				return true
520			}
521		}
522		for _, decl := range file.Decls {
523			fn := ""
524			if fd, ok := decl.(*ast.FuncDecl); ok {
525				fn = fd.Name.Name
526			}
527			ast.Inspect(decl, visit(fn))
528		}
529		return out
530	}
